const data = pm.response.json();

if (pm.response.code === 200 && data.access_token) {
    pm.environment.set("access_token", data.access_token);
    pm.environment.set("refresh_token", data.refresh_token);
    pm.environment.set("user_id", data.user.id);

    console.log("Access token сохранён");
} else {
    console.log("Не удалось сохранить токен");
}

pm.test("Статус 200", function () { pm.expect(pm.response.code).to.be.oneOf([200]); });
pm.test("Есть заголовок Content-Range", function () { pm.expect(pm.response.headers.has("Content-Range")).to.be.true; });
const d = pm.response.json();
if (Array.isArray(d) && d.length) { pm.environment.set("case_id", d[0].id); console.log("case_id =", d[0].id); }
pm.test("В ответе есть хотя бы один элемент", function () { pm.expect(d.length).to.be.at.least(1); });
pm.test("В ответе есть поле id", function () { pm.expect(d[0]).to.have.property("id"); });
pm.test("В ответе есть поле title", function () { pm.expect(d[0]).to.have.property("title"); });
pm.test("В ответе есть поле introduction", function () { pm.expect(d[0]).to.have.property("introduction"); });
pm.test("В ответе есть поле difficulty", function () { pm.expect(d[0]).to.have.property("difficulty"); });
pm.test("В ответе есть поле create_at", function () { pm.expect(d[0]).to.have.property("create_at"); });

const data = pm.response.json();

pm.test("Ответ является массивом", function () {
    pm.expect(data).to.be.an("array");
});

pm.test("Каждое дело имеет идентификатор", function () {
    data.forEach(item => {
        pm.expect(item).to.have.property("id");
    });
});

pm.test("Каждое дело имеет название", function () {
    data.forEach(item => {
        pm.expect(item).to.have.property("title");
    });
});
